package com.autosphere.controller;
import com.autosphere.model.*;import com.autosphere.repository.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/admin") public class AdminController {private final VehicleRepository vehicles;private final CityPriceRepository prices;public AdminController(VehicleRepository v,CityPriceRepository p){vehicles=v;prices=p;}public record VehicleInput(@NotBlank String stockId,@NotBlank String type,@NotBlank String model,String variant,String fuel,int year,long kilometres,@Positive long exShowroomPrice,String imageUrl,String description){}@PostMapping("/vehicles") public Vehicle add(@Valid @RequestBody VehicleInput r){Vehicle v=new Vehicle();v.stockId=r.stockId();v.type=r.type();v.model=r.model();v.variant=r.variant();v.fuel=r.fuel();v.year=r.year();v.kilometres=r.kilometres();v.exShowroomPrice=r.exShowroomPrice();v.imageUrl=r.imageUrl();v.description=r.description();return vehicles.save(v);}public record PriceInput(@NotBlank String city,@PositiveOrZero long roadTax,@PositiveOrZero long insurance,@PositiveOrZero long accessories){}@PutMapping("/pricing/{vehicleId}") public CityPrice setPrice(@PathVariable Long vehicleId,@Valid @RequestBody PriceInput r){Vehicle v=vehicles.findById(vehicleId).orElseThrow();CityPrice p=prices.findByVehicleIdAndCityIgnoreCase(vehicleId,r.city()).orElse(new CityPrice(v,r.city(),0,0,0));p.roadTax=r.roadTax();p.insurance=r.insurance();p.accessories=r.accessories();return prices.save(p);}}
